  local delivery_log="/home/dieterolson/gaai-fleet/UpstreamDrift/.gaai/core/../project/contexts/backlog/.delivery-logs/GH1957.log"
  local fields_updated=0

  # cost_usd — from delivery log (type:result → total_cost_usd)
  if [[ -f "$delivery_log" ]]; then
    local cost
    cost=$(python3 - "$delivery_log" <<'PYEOF'
