try:
    with open(sys.argv[1]) as f:
        for line in f:
            try:
                d = json.loads(line.strip())
                if d.get('type') == 'result':
                    c = d.get('total_cost_usd') or d.get('costUSD') or 0
                    if c:
                        print(round(float(c), 4))
                        sys.exit(0)
            except: pass
except: pass
PYEOF
    2>/dev/null) || cost=""
    if [[ -n "$cost" && "$cost" != "0" ]]; then
      "/home/dieterolson/gaai-fleet/UpstreamDrift/.gaai/core/scripts/backlog-scheduler.sh" --set-field "GH1957" cost_usd "$cost" "/home/dieterolson/gaai-fleet/UpstreamDrift/.gaai/project/contexts/backlog/active.backlog.yaml" 2>/dev/null && {
        fields_updated=1
        echo "[WRAPPER] cost_usd=$cost"
