      pr_number=$(echo "$pr_json" | python3 -c "import json,sys; d=json.load(sys.stdin); print(d[0].get('number',''))" 2>/dev/null) || pr_number=""
      pr_state=$(echo "$pr_json" | python3 -c "import json,sys; d=json.load(sys.stdin); s=d[0]; print('merged' if s.get('mergedAt') else s.get('state','open').lower())" 2>/dev/null) || pr_state=""
      [[ -n "$pr_url" ]] && "/home/dieterolson/gaai-fleet/UpstreamDrift/.gaai/core/scripts/backlog-scheduler.sh" --set-field "GH1957" pr_url "$pr_url" "/home/dieterolson/gaai-fleet/UpstreamDrift/.gaai/project/contexts/backlog/active.backlog.yaml" 2>/dev/null && fields_updated=1
      [[ -n "$pr_number" ]] && "/home/dieterolson/gaai-fleet/UpstreamDrift/.gaai/core/scripts/backlog-scheduler.sh" --set-field "GH1957" pr_number "$pr_number" "/home/dieterolson/gaai-fleet/UpstreamDrift/.gaai/project/contexts/backlog/active.backlog.yaml" 2>/dev/null && fields_updated=1
      [[ -n "$pr_state" ]] && "/home/dieterolson/gaai-fleet/UpstreamDrift/.gaai/core/scripts/backlog-scheduler.sh" --set-field "GH1957" pr_status "$pr_state" "/home/dieterolson/gaai-fleet/UpstreamDrift/.gaai/project/contexts/backlog/active.backlog.yaml" 2>/dev/null && fields_updated=1
    fi
