          '/home/dieterolson/gaai-fleet/UpstreamDrift/.gaai/core/scripts/backlog-scheduler.sh' --set-status 'GH1957' failed '/home/dieterolson/gaai-fleet/UpstreamDrift/.gaai/project/contexts/backlog/active.backlog.yaml' 2>/dev/null || true
